@once
<style>
#messageComposer[data-buyer-composer]{flex-direction:row;align-items:flex-end}#messageComposer[data-buyer-composer]>div{min-width:0}#messageComposer[data-buyer-composer] textarea{box-sizing:border-box;resize:none;overflow-y:hidden;line-height:20px;padding:11px 13px;min-height:44px;max-height:124px}#messageComposer[data-buyer-composer] button[type=submit]{min-height:44px;flex-shrink:0}#messageComposer[data-buyer-composer] button:disabled{opacity:.5;cursor:wait}
.message-image-gallery [hidden],.message-image-lightbox [hidden]{display:none!important}.message-image-gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:8px;width:360px;max-width:100%}.message-image-gallery.is-single{grid-template-columns:1fr;width:260px}.message-image-gallery button{position:relative;padding:0;overflow:hidden;border:1px solid #dce5e0;border-radius:10px;background:#e9f0ec;cursor:pointer;aspect-ratio:4/3;min-width:0}.message-image-gallery img{display:block;width:100%;height:100%;object-fit:cover}.message-image-more{position:absolute;inset:0;display:grid;place-items:center;background:#102c2580;color:white;font-size:24px;font-weight:600}.message-image-fallback{display:grid;place-items:center;position:absolute;inset:0;color:#52635b;background:#edf3ef;font-size:11px}.message-image-lightbox{position:fixed;inset:0;margin:auto;width:calc(100% - 24px);max-width:1000px;max-height:calc(100dvh - 24px);padding:16px;border:1px solid #dde6e1;border-radius:14px;background:#fff;color:#173f35;overflow:auto;font-family:inherit}.message-image-lightbox::backdrop{background:#102c25cc;backdrop-filter:blur(3px)}.message-image-lightbox header,.message-image-lightbox footer{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px}.message-image-lightbox h2{font-size:14px;font-weight:600;margin:0;overflow-wrap:anywhere}.message-image-lightbox button,.message-image-lightbox a{min-height:40px;padding:8px 12px;border:1px solid #cadbd1;border-radius:8px;font:inherit;font-size:12px;background:white;color:#173f35;cursor:pointer}.message-image-lightbox a{background:#173f35;color:white}.message-image-lightbox footer>span{font-size:12px}.message-lightbox-image{display:grid;place-items:center;min-height:180px;margin:14px 0;background:#f4f8f5;border-radius:10px;overflow:hidden}.message-lightbox-image img{max-width:100%;max-height:70dvh;object-fit:contain}.message-image-gallery button:focus-visible,.message-image-lightbox :is(button,a):focus-visible{outline:3px solid #1f6f5b;outline-offset:2px}.inbox-new-messages{bottom:calc(var(--inbox-composer-height,78px) + 12px)}
@media(max-width:540px){.message-image-gallery{width:270px}.message-image-gallery.is-single{width:230px}.message-image-lightbox{padding:12px}.message-image-lightbox footer button,.message-image-lightbox footer a{font-size:11px;padding:8px}}
</style>
@endonce
